<script setup>
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';
import {useRoute,useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';
import http from './api/http';import Chart from './components/Chart.vue';
const route=useRoute(),router=useRouter();
const role=ref(localStorage.getItem('qr-role')||''),username=ref(localStorage.getItem('qr-user')||'');
const canWrite=computed(()=>['ADMIN','ANALYST'].includes(role.value));
const admin=computed(()=>role.value==='ADMIN');const loading=ref(false),failed=ref(false);
const nav=[['/dashboard','◫','质量驾驶舱','总览与趋势'],['/products','◈','商品质量分析','画像与证据'],['/mining','⌘','评论挖掘','数据与任务'],['/alerts','△','预警与处置','异常与追踪'],['/admin','⚙','系统管理','配置与开发']];
const title=computed(()=>nav.find(n=>route.path.startsWith(n[0]))?.[2]||(route.path.startsWith('/product/')?'商品质量画像':'质衡'));
const login=reactive({username:'admin',password:'',captcha:'2026'});
const dictionaries=ref({categories:[],suppliers:[],params:[],rules:[]}),overview=ref(null),products=ref({items:[],total:0}),profile=ref(null),comments=ref({items:[],total:0}),tasks=ref([]),batches=ref([]),alerts=ref({items:[],total:0}),health=ref(null);
const filters=reactive({keyword:'',category:'',page:1,status:'',level:'',dimension:'',sentiment:'',fake:''});
const task=reactive({scope_type:1,scope_value:'900000001',param_version:'v1-2026-10',period_start:'2026-11-01',period_end:'2026-11-09'});
const disposal=reactive({open:false,id:0,status:1,note:'',row:null});
const management=ref('rules'),adminRows=ref([]),editor=ref(''),dialog=ref(false),editorTitle=ref('');
const detail=ref(null),detailOpen=ref(false);let poll;
const dimensionNames={quality:'商品质量',appearance:'外观设计',logistics:'物流配送',service:'客服服务',value:'性价比',package:'包装完好'};
const grades={1:'极差',2:'差',3:'中',4:'良',5:'优'};const statuses=['待处置','已确认','已忽略','已处理'];const taskStatuses=['排队中','运行中','成功','失败','已取消'];
const fmt=(v,n=1)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:n});
const time=v=>v?String(v).replace('T',' ').slice(0,19):'—';
const latest=computed(()=>profile.value?.indices?.[0]);
const lineOption=items=>({color:['#0c8778'],tooltip:{trigger:'axis'},grid:{left:45,right:20,top:25,bottom:35},xAxis:{type:'category',data:items.map(x=>String(x.period_start).slice(0,10)),axisLine:{lineStyle:{color:'#dfe8e5'}},axisLabel:{color:'#81928c'}},yAxis:{type:'value',min:0,max:100,splitLine:{lineStyle:{color:'#edf2ef'}},axisLabel:{color:'#81928c'}},series:[{type:'line',smooth:true,symbolSize:6,data:items.map(x=>x.qi),areaStyle:{color:'#0c877812'}}]});
const trend=computed(()=>lineOption(overview.value?.trend||[]));
const productTrend=computed(()=>lineOption([...(profile.value?.indices||[])].filter((x,i,a)=>a.findIndex(y=>y.period_start===x.period_start)===i).reverse()));
const rankOption=computed(()=>({color:['#0c8778'],tooltip:{trigger:'axis'},grid:{left:110,right:30,top:15,bottom:20},xAxis:{type:'value',max:100,splitLine:{lineStyle:{color:'#edf2ef'}}},yAxis:{type:'category',data:(overview.value?.ranking||[]).map(x=>x.name.slice(0,10)),axisTick:{show:false},axisLine:{show:false}},series:[{type:'bar',barWidth:13,itemStyle:{borderRadius:[0,5,5,0]},data:(overview.value?.ranking||[]).map(x=>x.qi)}]}));
const radar=computed(()=>({color:['#0c8778'],tooltip:{},radar:{indicator:Object.entries(dimensionNames).map(([k,n])=>({name:n,max:1})),radius:'64%',axisName:{color:'#557168'},splitArea:{areaStyle:{color:['#fff','#f5faf8']}}},series:[{type:'radar',areaStyle:{opacity:.18},data:[{name:'维度得分',value:Object.keys(dimensionNames).map(k=>latest.value?.dims?.find(d=>d.code===k)?.score||0)}]}]}));
const distribution=computed(()=>({color:['#0c8778','#dfb75d','#dc7669'],tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['45%','70%'],label:{formatter:'{b}\n{d}%'},data:[1,0,-1].map((s,i)=>({name:['正面','中性','负面'][i],value:profile.value?.distribution?.find(d=>d.sentiment===s)?.n||0}))}]}));
async function signIn(){loading.value=true;try{let d=await http.post('/auth/login',login);localStorage.setItem('qr-token',d.token);localStorage.setItem('qr-role',d.role);localStorage.setItem('qr-user',d.username);role.value=d.role;username.value=d.username;await router.push('/dashboard');}finally{loading.value=false;}}
function logout(){localStorage.removeItem('qr-token');router.push('/login');}
function sync(){router.replace({path:route.path,query:Object.fromEntries(Object.entries(filters).filter(([k,v])=>v!==''&&v!==1))});}
async function load(){
 if(route.path==='/login')return;if(!localStorage.getItem('qr-token')){router.replace('/login');return;}
 loading.value=true;failed.value=false;
 try{
  dictionaries.value=await http.get('/dictionaries');
  if(route.path==='/dashboard')overview.value=await http.get('/dashboard/overview',{params:{category:filters.category}});
  else if(route.path==='/products')products.value=await http.get('/products',{params:filters});
  else if(route.path.startsWith('/product/')){profile.value=await http.get(`/products/${route.path.split('/')[2]}/profile`);await loadComments();}
  else if(route.path==='/mining'){[tasks.value,batches.value]=await Promise.all([http.get('/mining/tasks'),http.get('/imports')]);}
  else if(route.path==='/alerts')alerts.value=await http.get('/alerts',{params:filters});
  else if(route.path==='/admin'&&admin.value){await loadAdmin();health.value=await http.get('/system/health');}
 }catch(e){failed.value=true;}finally{loading.value=false;}
}
async function loadComments(){comments.value=await http.get('/reviews',{params:{...filters,product_id:route.path.split('/')[2]}});}
async function loadAdmin(){const d=await http.get('/admin/'+management.value);if(management.value==='aspect-dict'){editor.value=JSON.stringify(d,null,2);adminRows.value=[];}else adminRows.value=d;}
async function upload(e){const file=e.target.files[0];if(!file)return;let f=new FormData();f.append('file',file);loading.value=true;try{const b=await http.post('/imports',f);ElMessage.success(`批次 ${b.id}：成功 ${b.success}，失败 ${b.failed}`);await load();}finally{loading.value=false;e.target.value='';}}
async function undo(id){await ElMessageBox.confirm('撤销会删除本批评论，并清除受影响商品的旧指数。需要重新挖掘计算。','撤销批次',{type:'warning'});await http.post(`/imports/${id}/undo`);await load();}
async function startTask(){await http.post('/mining/tasks',{...task});ElMessage.success('任务已提交，可在下方查看进度');await load();}
async function scan(){loading.value=true;try{let d=await http.post('/alerts/scan');ElMessage.success(`扫描完成，新增 ${d.created} 条预警`);await load();}finally{loading.value=false;}}
function showDispose(row){Object.assign(disposal,{open:true,id:row.id,status:1,note:'',row});}
async function dispose(){if(!disposal.note.trim()){ElMessage.warning('请填写处置意见');return;}await http.post(`/alerts/${disposal.id}/dispose`,{status:disposal.status,note:disposal.note});disposal.open=false;ElMessage.success('处置记录已保存');await load();}
async function exportReport(type='products',format='csv'){const blob=await http.get('/reports/export',{params:{type,format,product_id:route.path.startsWith('/product/')?route.path.split('/')[2]:0,...filters},responseType:'blob'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`质量报告-${type}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openEditor(row){editorTitle.value=row?'编辑配置':'新建记录';let defaults={products:{id:990000001,name:'新商品',category_id:0,supplier_id:1},categories:{id:100001,name:'新品类'},suppliers:{id:101,name:'新供应商'},users:{username:'new_user',password:'',role:'VIEWER'},params:{version:'v2-2026-11',params:JSON.parse(dictionaries.value.params[0]?.params_json||'{}')}};let value=row?{...row}:defaults[management.value];if(value?.threshold_json)value.threshold_json=JSON.parse(value.threshold_json);editor.value=JSON.stringify(value||{},null,2);dialog.value=true;}
async function saveConfig(){let value;try{value=JSON.parse(editor.value);}catch{ElMessage.error('JSON 格式错误');return;}await http.post('/admin/'+management.value,value);dialog.value=false;ElMessage.success('配置已保存，重算任务将使用新配置');await loadAdmin();}
function evidence(row){detail.value=row;detailOpen.value=true;}
function chooseDim(code){filters.dimension=code;filters.page=1;sync();loadComments();}
watch(()=>route.fullPath,()=>{Object.assign(filters,{keyword:'',category:'',page:1,status:'',level:'',dimension:'',sentiment:'',fake:''},route.query);load();},{immediate:true});
poll=setInterval(async()=>{if(route.path==='/mining'&&tasks.value.some(t=>t.status<2)){tasks.value=await http.get('/mining/tasks').catch(()=>tasks.value);}},2500);onBeforeUnmount(()=>clearInterval(poll));
</script>

<template>
 <div v-if="route.path==='/login'" class="login-page"><div class="login-story"><div class="brand"><b>衡</b><span>质衡 QUALITY LENS</span></div><div><span class="eyebrow">REVIEW INTELLIGENCE / QUALITY MANAGEMENT</span><h1>从每一条评论，<br>看见产品的真实质量。</h1><p>接入 · 挖掘 · 度量 · 处置 · 呈现</p><div class="login-orbit"><i></i><i></i><i></i><strong>QI<span>可解释的质量度量</span></strong></div></div><small>本地部署 · 可复算指标 · 可追溯处置</small></div><div class="login-form"><span class="eyebrow">WELCOME BACK</span><h2>登录质量工作台</h2><p class="muted">使用管理员、分析师或只读账号进入系统</p><el-form label-position="top" @submit.prevent="signIn"><el-form-item label="账号"><el-input v-model="login.username" size="large" autocomplete="username" /></el-form-item><el-form-item label="口令"><el-input v-model="login.password" type="password" show-password size="large" autocomplete="current-password" @keyup.enter="signIn" /></el-form-item><el-form-item label="演示验证码（2026）"><el-input v-model="login.captcha" size="large" /></el-form-item><el-button type="primary" size="large" class="full" :loading="loading" @click="signIn">进入工作台 →</el-button></el-form><p class="muted tiny">初始账号：admin / analyst / viewer<br>初始口令见交付包 README，可通过环境变量修改。</p></div></div>
 <div v-else class="shell"><aside><div class="brand"><b>衡</b><div>质衡<span>QUALITY LENS</span></div></div><div class="nav-label">质量管理工作台</div><nav><router-link v-for="n in nav.filter(x=>x[0]!='/admin'||admin)" :key="n[0]" :to="n[0]" :class="{active:route.path.startsWith(n[0])}"><i>{{n[1]}}</i><div>{{n[2]}}<small>{{n[3]}}</small></div></router-link></nav><div class="sidebar-foot"><span class="live-dot"></span> 单机部署 / 开发可扩展<p>数据驱动质量 · 让决策有据</p></div></aside>
 <section class="workspace"><header><div class="breadcrumb">质量管理 <span>/</span> {{title}}</div><div class="header-right"><span class="live-dot"></span> 本地工作空间 <span class="avatar">{{username.slice(0,1).toUpperCase()}}</span><span>{{username}} <small>{{role}}</small></span><button class="text-button" @click="logout">退出</button></div></header>
 <main v-loading="loading"><div class="page-heading"><div><span class="eyebrow">QUALITY INTELLIGENCE PLATFORM</span><h1>{{title}}<span class="edition">V1.0</span></h1><p>让评论成为可解释、可追溯的质量信号</p></div><div class="actions"><el-button @click="load">↻ 刷新</el-button><el-button v-if="['/dashboard','/products','/alerts'].includes(route.path)" type="primary" @click="exportReport(route.path==='/alerts'?'alerts':'products')">↓ 导出报告</el-button></div></div>
 <el-alert v-if="failed" title="加载失败，请检查后台服务并点击刷新重试。" type="error" show-icon :closable="false" />
 <template v-if="route.path==='/dashboard'&&overview"><div class="notice"><span>数据说明</span>{{overview.disclosure}}</div><div class="toolbar"><el-select v-model="filters.category" filterable clearable placeholder="全部品类" @change="sync" style="width:220px"><el-option v-for="c in dictionaries.categories" :key="c.id" :label="c.name" :value="String(c.id)" /></el-select><span class="muted">13 个月归一化演示周期 · 月度预计算</span></div>
 <div class="metrics"><article v-for="(x,i) in [['在监商品',overview.stats.products,'件'],['平均质量指数',overview.stats.average_qi,'/100'],['本周新增预警',overview.stats.weekly_alerts,'条'],['待处置预警',overview.stats.pending,'条']]" :key="x[0]"><span class="metric-icon">{{['◈','◎','△','◷'][i]}}</span><p>{{x[0]}}</p><strong>{{fmt(x[1])}}<small>{{x[2]}}</small></strong><div class="metric-note">{{['覆盖 '+fmt(overview.stats.reviews,0)+' 条评论','六维加权 · 贝叶斯收缩','分级扫描 · 七日抑制','逾期 '+overview.stats.overdue+' 条'][i]}}</div></article></div>
 <div class="chart-grid"><section class="panel"><div class="panel-title"><div><h3>质量指数趋势</h3><p>同周期在监商品指数均值</p></div><span class="legend-dot">综合 QI</span></div><Chart :option="trend" /></section><section class="panel"><div class="panel-title"><div><h3>重点关注品类</h3><p>按当前质量指数从低到高</p></div><span class="tag">TOP 8</span></div><Chart :option="rankOption" /></section></div>
 <section class="panel"><div class="panel-title"><div><h3>最新质量预警 <span class="badge">{{overview.stats.pending}} 待办</span></h3><p>从异常信号下钻到商品与评论证据</p></div><el-button link type="primary" @click="router.push('/alerts')">查看全部 →</el-button></div><el-table :data="overview.alerts" empty-text="尚无预警；到预警页执行扫描"><el-table-column label="预警级别" width="110"><template #default="{row}"><span :class="'severity s'+row.level">{{['','黄色','橙色','红色'][row.level]}}</span></template></el-table-column><el-table-column prop="product_name" label="商品" min-width="260" show-overflow-tooltip /><el-table-column label="状态" width="110"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column label="触发时间" width="190"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="router.push('/product/'+row.product_id)">查看画像 →</el-button></template></el-table-column></el-table></section>
 </template>
 <template v-if="route.path==='/products'"><section class="panel"><div class="toolbar"><el-input v-model="filters.keyword" placeholder="搜索商品名称" clearable @keyup.enter="sync" style="width:280px"/><el-select v-model="filters.category" filterable clearable placeholder="全部品类" style="width:220px"><el-option v-for="c in dictionaries.categories" :key="c.id" :label="c.name" :value="String(c.id)" /></el-select><el-button type="primary" @click="filters.page=1;sync()">检索商品</el-button><span class="muted">共 {{fmt(products.total,0)}} 件</span></div><el-table :data="products.items"><el-table-column prop="id" label="商品编号" width="130"/><el-table-column prop="name" label="商品名称" min-width="260" show-overflow-tooltip/><el-table-column prop="category_name" label="品类" width="140"/><el-table-column label="质量指数" width="120"><template #default="{row}"><strong class="score-text">{{fmt(row.qi)}}</strong></template></el-table-column><el-table-column label="等级" width="80"><template #default="{row}">{{grades[row.grade]||'未分析'}}</template></el-table-column><el-table-column prop="sample_size" label="本期样本" width="100"/><el-table-column width="110"><template #default="{row}"><el-button link type="primary" @click="router.push('/product/'+row.id)">查看画像 →</el-button></template></el-table-column></el-table><el-pagination layout="prev,pager,next,total" :total="products.total" :page-size="20" v-model:current-page="filters.page" @current-change="sync"/></section></template>
 <template v-if="route.path.startsWith('/product/')&&profile"><div class="product-banner"><div><el-button link @click="router.push('/products')">← 商品列表</el-button><h2>{{profile.product.name}}</h2><p>{{profile.product.category_name}} · {{profile.product.supplier_name}} <span v-if="profile.product.scenario" class="badge">模拟剧本 {{profile.product.scenario}}</span></p></div><div class="qi-big">{{fmt(latest?.qi)}}<small>{{grades[latest?.grade]||'未分析'}}</small></div></div><el-alert v-if="!latest" title="暂无分析结果，请前往评论挖掘创建该商品任务。" type="info" :closable="false"/><el-alert v-else-if="latest.sample_size<30" title="本期样本不足30条，指数仅供参考。" type="warning" :closable="false"/><div class="notice"><span>参数版本 {{latest?.param_version||'—'}}</span>{{profile.summary}}</div><div class="triple"><section class="panel"><h3>六维质量雷达</h3><Chart :option="radar"/><div class="dimension-links"><button v-for="(n,k) in dimensionNames" :key="k" @click="chooseDim(k)">{{n}} ↘</button></div></section><section class="panel"><h3>历史质量趋势</h3><Chart :option="productTrend"/></section><section class="panel"><h3>评论情感分布</h3><Chart :option="distribution"/></section></div><section class="panel"><div class="panel-title"><h3>差评方面关键词</h3><span class="muted">按方面词频归纳，可点击下钻</span></div><div class="keywords"><span v-for="(v,k) in profile.keywords" :key="k">{{k}} <b>{{v}}</b></span><span v-if="!Object.keys(profile.keywords).length">暂无负面方面，尝试查看全部评论</span></div></section><section class="panel"><div class="panel-title"><h3>评论证据 · 组合检索</h3><el-button @click="exportReport('reviews')">导出筛选评论</el-button></div><div class="toolbar"><el-select v-model="filters.dimension" clearable placeholder="全部维度" style="width:150px"><el-option v-for="(n,k) in dimensionNames" :key="k" :label="n" :value="k"/></el-select><el-select v-model="filters.sentiment" clearable placeholder="全部情感" style="width:150px"><el-option label="正面" value="1"/><el-option label="中性" value="0"/><el-option label="负面" value="-1"/></el-select><el-select v-model="filters.fake" clearable placeholder="全部风险" style="width:150px"><el-option label="疑似刷评 ≥0.3" value="1"/><el-option label="低风险 <0.3" value="0"/></el-select><el-button type="primary" @click="filters.page=1;sync();loadComments()">检索</el-button></div><el-table :data="comments.items"><el-table-column prop="content_clean" label="脱敏评论" min-width="350" show-overflow-tooltip/><el-table-column label="情感" width="80"><template #default="{row}">{{{1:'正面',0:'中性','-1':'负面'}[row.sentiment]||'待分析'}}</template></el-table-column><el-table-column prop="rating" label="星级" width="70"/><el-table-column label="风险分" width="90"><template #default="{row}">{{fmt(row.fake_prob,2)}}</template></el-table-column><el-table-column label="日期" width="120"><template #default="{row}">{{time(row.review_time).slice(0,10)}}</template></el-table-column><el-table-column width="100"><template #default="{row}"><el-button link type="primary" @click="evidence(row)">分析明细</el-button></template></el-table-column></el-table><el-pagination layout="prev,pager,next,total" :total="comments.total" :page-size="20" v-model:current-page="filters.page" @current-change="sync"/></section><section class="panel"><h3>指数历史与参数版本</h3><el-table :data="profile.indices.slice(0,40)"><el-table-column prop="period_start" label="周期开始"/><el-table-column prop="period_end" label="周期结束"/><el-table-column prop="qi" label="QI"/><el-table-column prop="sample_size" label="样本量"/><el-table-column prop="param_version" label="参数版本"/></el-table></section></template>
 <template v-if="route.path==='/mining'"><div class="notice"><span>数据治理</span>UTF-8 CSV · 入库前脱敏 · 标记重复 · 错误逐行报告 · 失败率超过50%整批回滚 · 单批最多50,000条</div><div class="chart-grid"><section class="panel"><div class="panel-title"><h3>接入评论数据</h3><span class="tag">M1</span></div><p class="muted">必填列：product_id、content_raw、rating、review_time；source_type 可选（1公开 / 2导出 / 3模拟）。商品需先在管理页创建。</p><label v-if="canWrite" class="upload-zone">＋<strong>选择 CSV 文件并导入</strong><small>时间格式：2026-11-09 12:00:00</small><input type="file" accept=".csv" @change="upload"/></label><el-alert v-else title="当前为只读账号，分析师或管理员可导入。" type="info" :closable="false"/></section><section class="panel"><div class="panel-title"><h3>创建挖掘与指数任务</h3><span class="tag">M2 → M3 → M4</span></div><el-form label-width="90px"><el-form-item label="分析范围"><el-select v-model="task.scope_type"><el-option label="单商品" :value="1"/><el-option label="品类" :value="2"/><el-option label="全部商品" :value="3"/></el-select><el-input v-if="task.scope_type!==3" v-model="task.scope_value" placeholder="填写编号" style="margin-top:8px"/></el-form-item><el-form-item label="参数版本"><el-select v-model="task.param_version"><el-option v-for="p in dictionaries.params" :key="p.version" :value="p.version" :label="p.version"/></el-select></el-form-item><el-form-item label="统计周期"><el-input v-model="task.period_start" style="width:46%"/><span style="padding:0 8px">至</span><el-input v-model="task.period_end" style="width:46%"/></el-form-item><el-form-item><el-button type="primary" :disabled="!canWrite" @click="startTask">启动挖掘 →</el-button><span class="muted tiny">后台执行，页面可继续操作</span></el-form-item></el-form></section></div><section class="panel"><h3>挖掘任务</h3><el-table :data="tasks"><el-table-column prop="id" label="任务" width="80"/><el-table-column prop="scope_value" label="范围编号" width="130"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===3?'danger':row.status===2?'success':'info'">{{taskStatuses[row.status]}}</el-tag></template></el-table-column><el-table-column label="进度" width="180"><template #default="{row}"><el-progress :percentage="row.progress"/></template></el-table-column><el-table-column prop="message" label="结果 / 错误环节" min-width="260"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.status<2&&canWrite" link type="danger" @click="http.post('/mining/tasks/'+row.id+'/cancel').then(load)">取消</el-button><el-button v-if="row.status===3&&canWrite" link @click="Object.assign(task,JSON.parse(row.params));startTask()">重试</el-button></template></el-table-column></el-table></section><section class="panel"><h3>导入批次与治理报告</h3><el-table :data="batches"><el-table-column prop="id" label="批次" width="80"/><el-table-column prop="file_name" label="文件" min-width="180"/><el-table-column prop="total" label="总行数"/><el-table-column prop="success" label="成功"/><el-table-column prop="failed" label="错误"/><el-table-column prop="skipped" label="重复标记"/><el-table-column label="状态"><template #default="{row}">{{['进行中','完成','失败回滚','已撤销'][row.status]}}</template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link @click="detail=row;detailOpen=true">错误明细</el-button><el-button v-if="canWrite&&row.status===1" link type="danger" @click="undo(row.id)">撤销</el-button></template></el-table-column></el-table></section></template>
 <template v-if="route.path==='/alerts'"><section class="panel"><div class="toolbar"><el-select v-model="filters.status" clearable placeholder="全部状态" style="width:150px"><el-option v-for="(s,i) in statuses" :key="i" :label="s" :value="String(i)"/></el-select><el-select v-model="filters.level" clearable placeholder="全部级别" style="width:150px"><el-option v-for="(s,i) in ['黄色','橙色','红色']" :key="i" :label="s" :value="String(i+1)"/></el-select><el-select v-model="filters.category" clearable filterable placeholder="全部品类" style="width:180px"><el-option v-for="c in dictionaries.categories" :key="c.id" :label="c.name" :value="String(c.id)"/></el-select><el-button type="primary" @click="filters.page=1;sync()">筛选</el-button><el-button :disabled="!canWrite" @click="scan">执行规则扫描</el-button><el-button @click="exportReport('alerts','pdf')">PDF 台账</el-button></div><el-table :data="alerts.items"><el-table-column label="级别" width="95"><template #default="{row}"><span :class="'severity s'+row.level">{{['','黄色','橙色','红色'][row.level]}}</span></template></el-table-column><el-table-column prop="product_name" label="商品" min-width="230" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column label="触发时间" width="170"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column prop="disposed_by" label="处置人" width="100"/><el-table-column label="操作" width="230"><template #default="{row}"><el-button link @click="detail=row;detailOpen=true">规则证据</el-button><el-button link type="primary" @click="router.push('/product/'+row.product_id)">画像</el-button><el-button v-if="admin&&row.status===0" link type="primary" @click="showDispose(row)">处置</el-button></template></el-table-column></el-table><el-pagination layout="prev,pager,next,total" :total="alerts.total" :page-size="20" v-model:current-page="filters.page" @current-change="sync"/></section><div class="notice"><span>口径说明</span>R1 综合指数 · R2 单维度 · R3 差评率突增 · R4 刷评风险占比 · R5 方面下滑。同商品合并最高级别，7日内抑制重复，升级更新原预警。</div></template>
 <template v-if="route.path==='/admin'"><el-alert v-if="!admin" title="系统管理仅管理员可访问。" type="warning"/><template v-else><div class="notice"><span>开发者工作台</span>词表与阈值可在线维护；新权重请创建独立参数版本再重算。源代码、算法与构建配置均可编辑。</div><section class="panel"><div class="panel-title"><h3>运行状态</h3><a href="/swagger-ui/index.html" target="_blank">业务 API 文档 ↗</a></div><pre class="health">{{JSON.stringify(health,null,2)}}</pre></section><section class="panel"><el-tabs v-model="management" @tab-change="loadAdmin"><el-tab-pane v-for="(label,key) in {rules:'预警规则',params:'指数参数',products:'商品',categories:'品类',suppliers:'供应商',users:'用户', 'aspect-dict':'方面词表',audit:'审计日志'}" :key="key" :name="key" :label="label"/></el-tabs><template v-if="management==='aspect-dict'"><p class="muted">JSON 包含 version、dimensions、features 和 synonyms。保存后重算生效。</p><el-input v-model="editor" type="textarea" :rows="20"/><el-button type="primary" style="margin-top:16px" @click="saveConfig">保存词表快照</el-button></template><template v-else><div class="toolbar"><el-button v-if="!['rules','audit'].includes(management)" type="primary" @click="openEditor()">＋ 新建{{management==='params'?'参数版本':'记录'}}</el-button><span class="muted">{{management==='params'?'历史版本不可覆盖，修改参数须创建新版本':'配置变更自动记录审计日志'}}</span></div><el-table :data="adminRows"><el-table-column v-for="key in Object.keys(adminRows[0]||{})" :key="key" :prop="key" :label="key" min-width="130" show-overflow-tooltip/><el-table-column v-if="management==='rules'" label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="openEditor(row)">调整阈值</el-button></template></el-table-column></el-table></template></section></template></template>
 <footer>质衡 / QUALITY LENS <span>公开评论研究数据 · 时间与供应商已加工标注 · 刷评分数仅表示规则风险</span></footer>
 </main></section></div>
 <el-dialog v-model="disposal.open" title="处置质量预警" width="540px"><p>{{disposal.row?.product_name}}</p><el-radio-group v-model="disposal.status"><el-radio :value="1">确认</el-radio><el-radio :value="2">忽略</el-radio><el-radio :value="3">标记已处理</el-radio></el-radio-group><el-input style="margin-top:20px" v-model="disposal.note" type="textarea" :rows="5" maxlength="500" show-word-limit placeholder="必填：判断依据、处理动作或忽略理由"/><template #footer><el-button @click="disposal.open=false">取消</el-button><el-button type="primary" @click="dispose">保存处置记录</el-button></template></el-dialog>
 <el-dialog v-model="dialog" :title="editorTitle" width="760px"><p class="muted">开发者配置：字段采用接口原名，JSON 格式；权重合计须为1，版本号不可重复。</p><el-input v-model="editor" type="textarea" :rows="18"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveConfig">校验并保存</el-button></template></el-dialog>
 <el-drawer v-model="detailOpen" title="证据与追溯明细" size="620px"><template v-if="detail?.aspects"><h3>评论原文（已脱敏）</h3><p class="evidence-text">{{detail.content_raw}}</p><p>模型 {{detail.model_version}} · 置信度 {{detail.confidence}} · 刷评风险 {{detail.fake_prob}}</p><h3>方面命中</h3><el-table :data="detail.aspects"><el-table-column prop="word" label="方面词"/><el-table-column prop="dimension" label="维度"/><el-table-column prop="strength" label="强度"/></el-table><h3>风险解释</h3><p v-for="h in detail.hits" :key="h.rule">{{h.rule}}（{{h.weight}}）：{{h.detail}}</p><p v-if="!detail.hits?.length" class="muted">未命中刷评风险规则。</p></template><pre v-else class="detail-json">{{JSON.stringify(detail,null,2)}}</pre></el-drawer>
</template>
